#include <stdio.h>

int main(void) {
    double pesos[] = {12.5, 8, 30.25, 4.75};   /* kg de cada bulto */
    double total = 0;
    for (int i = 0; i < 4; i++) {
        total = total + pesos[i];
    }
    printf("Total: %.2f kg\n", total);
    return 0;
}

